function speedforceCard(id, name, imgName, en, ru) {
  return {
    id: `speedforce-${id}`,
    name,
    img: `img/cards/speedforce/${imgName}.jpg`,
    renderAsCardImage: true,
    type: "Speedforce",
    category: "speedforce",
    mandatory: true,
    countsForDeck: false,
    requiredTrait: "Speedster",
    showWhenRequirementMet: true,
    showInlineText: false,
    text: { en, ru }
  };
}

