const weaponDescriptions = {
  "Batarang": "Ranged weapon. Ammo 3. Damage 1.",
  "Batarang (Ranged, Ammo 3)": "Ranged weapon. Ammo 3. Damage 1.",
  "Shock Gloves": "Close combat. Crit (Stunned).",
  "Combat Knife": "Close combat. Sharp.",
  "Military Pistol": "Ranged weapon. Range 12”. Damage 1.",
  "Grapnel Gun": "Movement tool. Straight line up to 12”.",
  "Smoke Grenade": "Creates a 3” smoke cloud that blocks LoS."
};

// ==================================================================
// ОБЪЕДИНЁННАЯ БАЗА ДЛЯ getDesc()
// ==================================================================

const descriptions = {
  ...traitDescriptions,
  ...weaponDescriptions
};

// Делаем всю базу доступной глобально для COMPENDIUM
window.compendium = { ...traitDescriptions};

// В data.js, замените существующую getDesc на это:
function getDesc(name) {
  if (!name) return "";
  
  const searchName = getCleanName(name);
  
  // 1. Сначала ищем прямое совпадение (на случай, если иконка уже в ключе)
  if (descriptions[name]) return descriptions[name];

  // 2. Универсальный поиск: перебираем все ключи в базе
  const allKeys = Object.keys(descriptions);
  for (let key of allKeys) {
    if (getCleanName(key) === searchName) {
      return descriptions[key];
    }
  }

  return "Description not found.";
}

// ======================== ЗАМЕНА ИКОНОК ========================
function replaceIcons(text) {
  if (typeof text !== 'string') return text || '';
  
  return text.replace(/\{([A-Z0-9+\-_]+_ICON)\}/gi, (match, tag) => {
    const imgSrc = `img/ico/${tag}.png`;
    return `<img src="${imgSrc}" alt="${tag}" class="stat-icon" style="height:20px; vertical-align:middle; margin:0 2px;">`;
  });
}

const factionNameAliases = {
  "GCPD": "Law Forces",
  "Bat Family": "Vigilantes",
  "Birds of Prey": "Harley Quinn & Friends",
  "Harley Quinn and Friends": "Harley Quinn & Friends",
  "League of Shadows": "League of Assassins",
  "Bane": "Soldiers of Fortune",
  "The Riddler": "Riddler",
  "Batman Who Laughs": "The Batman Who Laughs",
  "Court of Owls": "The Court of Owls",
  "Royal Flush": "Royal Flush Gang"
};

function canonicalFactionName(value) {
  const text = String(value || "").trim();
  return factionNameAliases[text] || text;
}

function normalizeFactionList(value) {
  const raw = Array.isArray(value)
    ? value.flat(Infinity)
    : typeof value === "string" && value.trim()
      ? (canonicalFactionName(value) !== value.trim()
          ? [value.trim()]
          : value.replace(/ *& */gi, ",").replace(/ *\/ */g, ",").split(","))
      : [];

  const seen = new Set();
  const result = [];
  for (const item of raw) {
    const faction = canonicalFactionName(item);
    if (!faction || seen.has(faction)) continue;
    seen.add(faction);
    result.push(faction);
  }
  return result;
}

function getFactions(model) {
  return normalizeFactionList(model?.faction);
}

function mergeFactionKeyedData(collection) {
  if (!collection || typeof collection !== "object") return collection;
  Object.keys(collection).forEach(key => {
    const canonical = canonicalFactionName(key);
    if (!canonical || canonical === key) return;

    const currentValue = collection[key];
    const existingValue = collection[canonical];
    if (Array.isArray(currentValue)) {
      collection[canonical] = Array.isArray(existingValue)
        ? [...existingValue, ...currentValue]
        : [...currentValue];
    } else if (currentValue && typeof currentValue === "object") {
      collection[canonical] = existingValue && typeof existingValue === "object" && !Array.isArray(existingValue)
        ? { ...currentValue, ...existingValue }
        : { ...currentValue };
    } else if (existingValue === undefined) {
      collection[canonical] = currentValue;
    }
    delete collection[key];
  });
  return collection;
}

mergeFactionKeyedData(factionCrewRules);
mergeFactionKeyedData(equipmentByFaction);
mergeFactionKeyedData(disabledLocalOnlyEquipmentByFaction);
if (typeof officialEquipmentRulesByFaction !== "undefined") mergeFactionKeyedData(officialEquipmentRulesByFaction);
if (typeof officialEquipmentByFactionExtensions !== "undefined") mergeFactionKeyedData(officialEquipmentByFactionExtensions);
if (typeof findOfficialEquipmentRule === "function" && typeof mergeOfficialEquipmentRuleFields === "function") {
  Object.keys(equipmentByFaction).forEach(faction => {
    equipmentByFaction[faction] = (equipmentByFaction[faction] || []).map(item =>
      mergeOfficialEquipmentRuleFields(item, findOfficialEquipmentRule(faction, item))
    );
  });
}
window.factionCrewRules = factionCrewRules;

function getRanks(model) {
  return Array.isArray(model.rank) ? model.rank : (typeof model.rank === 'string' ? [model.rank] : []);
}

function getRivals(model) {
  if (!model.rivals) return [];
  return normalizeFactionList(model.rivals);
}

// Экспортируем (чтобы была доступна в script.js)
window.getRivals = getRivals;

// Простая проверка — используется в режиме просмотра карточек (CARDS)
function canViewInFaction(model, faction) {
  const normalizedFaction = canonicalFactionName(faction);
  const factions = getFactions(model);
  return factions.includes(normalizedFaction);
}

// Расширенная проверка — используется ТОЛЬКО в билдере (CREWS)
// ======================== ПРАВИЛЬНАЯ ПРОВЕРКА НАЙМА В БИЛДЕРЕ ========================
function canHireInFaction(model, faction) {
  const normalizedFaction = canonicalFactionName(faction);
  const factions = getFactions(model);   // массив фракций модели
  const rivals   = getRivals(model);     // массив rivals модели

  const hasUnknown = factions.includes("Unknown");

  if (hasUnknown) {
    // Модель с Unknown — можно везде, КРОМЕ rivals
    return !rivals.includes(normalizedFaction);
  } else {
    // Обычная модель — только если фракция явно указана
    return factions.includes(normalizedFaction);
  }
}

// Экспорт (если нужно)
window.canViewInFaction = canViewInFaction;
window.canHireInFaction = canHireInFaction;

